1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Scenario {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	}
17	
18	export interface ScenarioOutput {
19	  results: unknown[];
20	}
21	
22	const PROCESSING_FEE = 5;
23	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
24	
25	const BASE_PREMIUMS: Record<string, number | undefined> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	  moonstone: 25,
32	};
33	
34	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
35	
36	const CURSE_SURCHARGE_RATE = 0.5;
37	const HIGH_ENCHANTMENT_LEVEL = 5;
38	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
39	
40	/** Item-specific modifiers apply to the base premium of the affected item only. */
41	const itemSurchargesOf = (item: Item): number => {
42	  const basePremium = basePremiumOf(item);
43	  const curseSurcharge = item.cursed === true ? basePremium * CURSE_SURCHARGE_RATE : 0;
44	  const highEnchantmentSurcharge =
45	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
46	  return curseSurcharge + highEnchantmentSurcharge;
47	};
48	
49	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
50	const COMPONENT_BLOCK_SIZE = 3;
51	const COMPONENT_BLOCK_PREMIUM = 60;
52	
53	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
54	
55	const countByType = (items: Item[]): Map<string, number> => {
56	  const counts = new Map<string, number>();
57	  for (const item of items) {
58	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
59	  }
60	  return counts;
61	};
62	
63	/**
64	 * Items of one type are normally priced individually. The exception is
65	 * components: exactly 3 alike ones form a "building block" priced as a unit.
66	 */
67	const typeGroupPremium = (type: string, count: number): number =>
68	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
69	    ? COMPONENT_BLOCK_PREMIUM
70	    : count * basePremiumOf({ type });
71	
72	const policyBasePremiumOf = (step: QuoteStep): number =>
73	  [...countByType(step.items)].reduce(
74	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
75	    0,
76	  );
77	
78	/** Kept as an exact fraction — only the final premium is rounded. */
79	const premiumBeforeRounding = (step: QuoteStep): number => {
80	  const policyBasePremium = policyBasePremiumOf(step);
81	  const itemSurcharges = step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
82	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
83	  return policyBasePremium + itemSurcharges + initialAssessmentSurcharge + PROCESSING_FEE;
84	};
85	
86	/** Rounded up, in the MHPCO's favour. */
87	const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));
88	
89	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
90	  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
91	});
